"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1091-01-01:0":{"b": ["فرمانده‌ای که به الموت فرستاده شده بود، یورونتاش، هنگام محاصره می‌میرد؛ لشکرکشی بی‌نتیجه می‌ماند (484/1091).", "146eafb7"], "d": ["فرمانده‌ای که به الموت فرستاده شده بود، یورونتاش، هنگام محاصره می‌میرد؛ لشکرکشی بی‌نتیجه می‌ماند (484/1091).", "146eafb7"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1095-01-01:0":{"b": ["نزار در زندان اسکندریه کشته می‌شود (488/1095)؛ دعوت نزاری جدا از مصر ادامه می‌یابد.", "834e214d"], "d": ["نزار در زندان اسکندریه کشته می‌شود (488/1095)؛ دعوت نزاری جدا از مصر ادامه می‌یابد.", "834e214d"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1107-06-01:0":{"b": ["سرخاب بن بدر می‌میرد (شوال 500 / ژوئن 1107)؛ ابومنصور جانشین او می‌شود.", "a1931e53"], "d": ["سرخاب بن بدر می‌میرد (شوال 500 / ژوئن 1107)؛ ابومنصور جانشین او می‌شود.", "a1931e53"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1109-07-31:0":{"b": ["وزیر احمد بن نظام‌الملک با سپاهی بزرگ به الموت فرستاده شد؛ به سبب زمستان نتیجه‌ای حاصل نشد", "ba5263e5"], "d": ["سلطان سلجوقی محمد تاپار برای از میان برداشتن حسن صباح وزیرش احمد بن نظام‌الملک را با سپاهی بزرگ به الموت گسیل داشت؛ لشکرکشی به سبب زمستان بی‌نتیجه ماند. محاصرهٔ اصلی در 1117 خواهد آمد.", "2e2a9c88"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1113-06-18:0":{"b": ["در حلب نمایندگان حسن صباح در سوریه و شمار بسیاری از باطنیان کشته شدند", "c70cc81f"], "d": ["سلطان سلجوقی محمد تاپار از الپ‌ارسلان اخرس، ملک حلب، و رئیس‌الاحداث سعید بن بدیع خواست باطنیان شهر کشته شوند؛ شمار بسیاری از باطنیان، با نمایندگان حسن صباح در سوریه چون ابوطاهر صائغ، اسماعیل داعی و برادر حکیم منجم، کشته شدند (507/1113).", "c7adbffa"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1117-01-01:0":{"b": ["خاندان عنازی پایان یافت (بر پایهٔ ثبت 130 سال ابن‌اثیر)", "a533a1d6"], "d": ["خاندان عنازی پایان یافت (بر پایهٔ ثبت 130 سال ابن‌اثیر)", "a533a1d6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1124-05-23:0":{"b": ["حسن صباح در الموت درگذشت", "1dccca4f"], "d": ["حسن صباح در الموت درگذشت", "1dccca4f"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1127-01-17:0":{"b": ["سلطان سنجر الموت را محاصره کرد؛ قلعه گرفته نشد", "6b06eb0c"], "d": ["سلطان سلجوقی سنجر در سال 521 (1127) الموت، مرکز اسماعیلیان نزاری، را محاصره کرد؛ فتح قلعه ممکن نشد.", "91215716"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1130-01-01:0":{"b": ["سلطان محمود بن محمد تاپار الموت را محاصره کرد؛ قلعه گرفته نشد", "64d6b833"], "d": ["سلطان سلجوقی محمود بن محمد تاپار در سال 524 (1130) الموت را محاصره کرد؛ قلعه سقوط نکرد.", "791399dc"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1130-01-01:1":{"b": ["Yeh-lü Ta-şi با برگزیدن بالاساغون به مرکزیت، دولت قراختاییان را بنیان نهاد", "b4157321"], "d": ["Yeh-lü Ta-şi با برگزیدن بالاساغون به مرکزیت، دولت قراختاییان را بنیان نهاد", "b4157321"]},
