"OLAYLAR_ORTACAG_ORTADOGU:0683-08-27:0":{"b": ["نبرد حره: سپاه اموی مدنیان را شکست داد", "a9d64a86"], "d": ["مسلم در حره، در شمال‌شرقی مدینه اردو زده بود؛ در نبردی که در 27 ذی‌الحجه 63 (27 اوت 683) میان مدنیان و نیروهای اموی درگرفت، مدنیان شکست خوردند.", "38032f7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0684-06-22:0":{"b": ["مروان یکم که در جابیه با او بیعت شد خلیفه شد؛ خلافت از شاخهٔ سفیانی به شاخهٔ مروانی رسید.", "264132fa"], "d": ["مروان یکم که در جابیه با او بیعت شد خلیفه شد؛ خلافت از شاخهٔ سفیانی به شاخهٔ مروانی رسید.", "264132fa"]},
"OLAYLAR_ORTACAG_ORTADOGU:0685-01-01:0":{"b": ["با مرگ مروان، پسرش عبدالملک بن مروان خلیفه شد (65/685؛ از نخستین خلفای اموی که چون پادشاهی عمل کرد).", "b0ed0613"], "d": ["با مرگ مروان، پسرش عبدالملک بن مروان خلیفه شد (65/685؛ از نخستین خلفای اموی که چون پادشاهی عمل کرد).", "b0ed0613"]},
